import{_ as t,o,c as n,a2 as i}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Knowledge Base","description":"","frontmatter":{"epic":16,"title":"Knowledge Base","status":"📋 Planned","scope":"mobile","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/mobile/knowledge-base.md"},"headers":[],"relativePath":"sovereign-edge/epics/mobile/knowledge-base.md","filePath":"sovereign-edge/epics/mobile/knowledge-base.md"}'),a={name:"sovereign-edge/epics/mobile/knowledge-base.md"};function s(r,e,d,l,c,h){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="epic-knowledge-base" tabindex="-1">Epic: Knowledge Base <a class="header-anchor" href="#epic-knowledge-base" aria-label="Permalink to &quot;Epic: Knowledge Base&quot;">​</a></h1><blockquote><p>An opt-in, on-device knowledge base the model can answer from: the user&#39;s own conversations, archived as they happen, plus content they add themselves. Fully offline — no connector, no network, nothing leaves the device.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Decided in <a href="./../../research/0012-knowledge-base-and-retrieval.html">research 0012</a> (option A), which is itself the continuation of <a href="./../../research/0006-files-document-summarization.html">research 0006</a>&#39;s parked question about whether document input wanted retrieval or just a length cap. 0006 established the architectural point this epic depends on: a corpus that lives on the device crosses no trust boundary, so this is a <strong>chat feature, not a connector</strong>. Nothing here touches the network, and nothing here goes through the Connector Framework.</p><p>A remote knowledge base — a self-hosted corpus reached over the network — is explicitly a <strong>second phase</strong>, and when it happens it goes through the connector layer under hard rule 2, per 0012&#39;s options B and C. It is not in this epic.</p><p>Three things make this larger than &quot;add retrieval&quot;:</p><ol><li><strong>The conversation archive is a new store, not a feature flag on the old one.</strong> <code>history.json</code> is destructively capped on write — <code>ChatScreen</code> calls <code>saveHistory(capMessages([...]))</code> every turn, so the oldest messages are deleted from disk as a conversation grows. That is correct for a working buffer sized to the next request&#39;s context, and it stays exactly as it is. The archive is separate: append-only and uncapped.</li><li><strong>Everything lives outside <code>src/chat/</code>.</strong> That module may not import <code>expo-file-system</code> at all (its own ESLint entry, because that module carries <code>DownloadTask</code>), nor <code>@/models</code> or <code>@/connectors</code>. The archive, the index, and retrieval all live in the app shell and reach chat through the injected <code>ChatSessionContext</code>, the same inversion <code>chatHistoryStore</code> and the engine already use.</li><li><strong>Local retrieval costs a second resident model.</strong> Embeddings need their own context — mobile&#39;s <code>embedding: boolean</code> context param and Rust&#39;s <code>EmbeddingsError::{NotEnabled, NonePoolType}</code> agree — and there is no embedding model in the catalog today. Whether a second resident context alongside a 1–4B chat model is viable on a mid-range Android device is the open question task 16.1 exists to answer, before anything is built on top of it.</li></ol><p>The LFM2 1.2B RAG model already in both catalogs (added in <code>a0f766c</code>, tuned to answer only from supplied text) is the intended generator. This epic is what finally gives it something to answer from.</p><p><strong>Sequencing note.</strong> This is prioritised ahead of the Sovereign Tasks connector (epic 4, roadmap slots 0.2.4/0.2.5), on the developer&#39;s explicit direction — the same way epics 10 and 11 were pulled ahead of it before, per research 0005 and 0009. Epic 4 is not cancelled, just later.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="📋-16-1-—-embedding-model-spike-and-catalog-entry" tabindex="-1">📋 16.1 — Embedding model spike and catalog entry <a class="header-anchor" href="#📋-16-1-—-embedding-model-spike-and-catalog-entry" aria-label="Permalink to &quot;📋 16.1 — Embedding model spike and catalog entry&quot;">​</a></h4><p><strong>Goal:</strong> Decide which embedding model this epic runs on, by measuring it on real hardware rather than comparing spec sheets — and establish whether a second resident context is viable at all.</p><p><strong>Deliverables:</strong></p><ul><li>A measured comparison of two or three small embedding GGUFs (nomic-embed-text and MiniLM class are the obvious candidates), on a real device, covering: embedding dimension, file size, load time, peak RSS when resident <em>alongside</em> an already-loaded chat model, and embed throughput for a realistic batch.</li><li>A go/no-go on the second resident context on a mid-range Android device. If it is not viable there, this epic&#39;s shape changes — say so loudly rather than proceeding and discovering it at 16.5.</li><li>The chosen model added to <code>apps/mobile/src/models/catalog.ts</code> with a real <code>sha256</code> and <code>sizeBytes</code>, following every existing entry&#39;s shape. Desktop catalog parity is deferred to 16.9.</li><li>Embedding surfaced on the engine wrapper in <code>src/chat/inference/</code> — <code>llama.rn</code>&#39;s <code>embedding()</code> behind the existing adapter shape, with the dedicated <code>embedding: true</code> / <code>pooling_type</code> context, kept separate from the chat context.</li></ul><p><strong>Dependencies:</strong> None. This gates every other task in the epic.</p><p><strong>Review checklist:</strong></p><ul><li>Measurements come from a real physical device, not a simulator — this repo&#39;s own convention, and memory pressure is exactly the thing a simulator will not tell you honestly.</li><li>Peak memory recorded with both models resident, not each alone.</li><li>The chosen model downloads, verifies against its recorded hash, and produces a vector of the expected dimension on-device.</li><li>No new network code outside <code>src/models/</code> (hard rule 3 covers acquiring a model; it does not license anything else).</li></ul><hr><h4 id="📋-16-2-—-conversation-archive-store" tabindex="-1">📋 16.2 — Conversation archive store <a class="header-anchor" href="#📋-16-2-—-conversation-archive-store" aria-label="Permalink to &quot;📋 16.2 — Conversation archive store&quot;">​</a></h4><p><strong>Goal:</strong> An append-only, uncapped record of conversations, written as they happen, separate from <code>history.json</code>.</p><p><strong>Deliverables:</strong></p><ul><li>A new store in the app shell alongside <code>chatHistoryStore.ts</code>, using the same <code>Paths.document</code> JSON pattern as chat history, connector grants, and installed connectors. Append-only; never capped.</li><li>Wired through <code>ModelSessionProvider</code>&#39;s existing <code>saveHistory</code> implementation rather than a new <code>ChatSessionContext</code> method — chat already calls it on every turn, and adding the archive there means <code>src/chat/</code> needs no new surface at all.</li><li><strong>Idempotent by message id.</strong> <code>ChatScreen</code> calls <code>saveHistory</code> twice per turn — once optimistically when the user sends, once when the reply settles — so a naive append double-writes every message and writes the assistant&#39;s reply once empty and once full.</li><li>Every entry tagged with its role, so retrieval can distinguish the user&#39;s own words from the model&#39;s (research 0012&#39;s &quot;indexing the model&#39;s own output&quot; risk).</li><li>Gated on the opt-in setting from 16.3: when off, nothing is written.</li></ul><p><strong>Dependencies:</strong> 16.3 (for the setting it reads). Independent of 16.1.</p><p><strong>Review checklist:</strong></p><ul><li>A conversation long enough to trigger <code>capMessages</code> still has its dropped messages present in the archive — the specific thing this task exists for.</li><li>Sending a message and letting the reply finish produces exactly one archive entry per message, with the assistant&#39;s final content, not its empty placeholder.</li><li>With the setting off, no archive file is created at all.</li><li><code>history.json</code>&#39;s own behaviour is byte-for-byte unchanged.</li></ul><hr><h4 id="📋-16-3-—-settings-opt-in-status-and-purge" tabindex="-1">📋 16.3 — Settings: opt-in, status, and purge <a class="header-anchor" href="#📋-16-3-—-settings-opt-in-status-and-purge" aria-label="Permalink to &quot;📋 16.3 — Settings: opt-in, status, and purge&quot;">​</a></h4><p><strong>Goal:</strong> The control surface. Off by default, honest about what is stored, and able to delete all of it.</p><p><strong>Deliverables:</strong></p><ul><li>A knowledge-base section in Settings: a single opt-in toggle, defaulting <strong>off</strong>, with copy stating plainly what gets stored when it is on.</li><li>Status: how many conversations/documents are archived, and how much disk they use.</li><li>A purge action that deletes the archive and the index, with a confirmation step.</li><li>Copy stating that opting in is <strong>not retroactive</strong> — everything <code>capMessages</code> already dropped is gone, and the archive starts now.</li></ul><p><strong>Dependencies:</strong> None (16.2 depends on this, not the reverse).</p><p><strong>Review checklist:</strong></p><ul><li>Default state on a fresh install is off, and nothing is archived until it is explicitly turned on.</li><li>Purge removes the files from disk, not just the in-memory state — verified by inspecting <code>Paths.document</code>, per hard rule 4&#39;s &quot;user-visible, user-deletable storage.&quot;</li><li>Turning the setting off stops archiving without destroying what is already archived (off ≠ purge — they are separate actions with separate copy).</li></ul><hr><h4 id="📋-16-4-—-chunking-and-the-index" tabindex="-1">📋 16.4 — Chunking and the index <a class="header-anchor" href="#📋-16-4-—-chunking-and-the-index" aria-label="Permalink to &quot;📋 16.4 — Chunking and the index&quot;">​</a></h4><p><strong>Goal:</strong> Turn archived text into retrievable, embedded chunks.</p><p><strong>Deliverables:</strong></p><ul><li>A chunker over archived conversations and user content. Fixed-size windows with overlap is the default; structure-aware splitting on markdown headings where the source has structure.</li><li>Vectors persisted alongside the chunks, as JSON in the same <code>Paths.document</code> pattern. <strong>No vector database</strong> — brute-force cosine over a personal-scale corpus is adequate until measured otherwise, and research 0003 is this repo&#39;s own precedent for not designing around an unmeasured assumption.</li><li><strong>Batch indexing, not per-turn.</strong> Indexing runs on an explicit trigger (opening the knowledge-base screen, or an &quot;index now&quot; action), so the embedding context is loaded for a bounded window rather than resident for the whole session. 0012&#39;s open question, resolved this way unless 16.1&#39;s measurements say otherwise.</li><li>Incremental: re-indexing only embeds what is new.</li></ul><p><strong>Dependencies:</strong> 16.1 (the model), 16.2 (something to index).</p><p><strong>Review checklist:</strong></p><ul><li>Indexing twice in a row does no work the second time and produces no duplicate chunks.</li><li>The embedding context is released after a batch, confirmed by memory returning to its pre-index level.</li><li>Chunk count and vector dimension match what 16.1 measured.</li></ul><hr><h4 id="📋-16-5-—-retrieval-and-context-injection" tabindex="-1">📋 16.5 — Retrieval and context injection <a class="header-anchor" href="#📋-16-5-—-retrieval-and-context-injection" aria-label="Permalink to &quot;📋 16.5 — Retrieval and context injection&quot;">​</a></h4><p><strong>Goal:</strong> Actually answer from the knowledge base.</p><p><strong>Deliverables:</strong></p><ul><li>Query-time retrieval: embed the query, cosine top-k over stored vectors, fold the winning passages into the request the existing offline pipeline already builds.</li><li>Reached from <code>src/chat/</code> only through an injected <code>ChatSessionContext</code> method, implemented by <code>ModelSessionProvider</code> — the same inversion as <code>loadHistory</code>/<code>saveHistory</code> and <code>generate</code>.</li><li>A character budget for injected passages, sitting alongside the existing <code>MESSAGE_HISTORY_CHAR_BUDGET</code> rather than eating into it, so retrieval cannot silently starve the conversation of context.</li><li>User-authored chunks preferred over assistant-authored ones at equal similarity, per 16.2&#39;s role tags.</li><li>No reranking. <code>rerank()</code> needs a third resident model (a cross-encoder in its own context) and is a later, measured upgrade — not part of a first cut.</li></ul><p><strong>Dependencies:</strong> 16.4.</p><p><strong>Review checklist:</strong></p><ul><li>A question whose answer appears only in an archived past conversation is answered correctly, and answered <em>wrongly</em> with the setting off — the paired check that proves retrieval is actually doing the work.</li><li>The offline boundary check (<code>pnpm check:offline</code>) still passes; <code>src/chat/</code> imports nothing new.</li><li>Injected passages plus history stay within budget on a long conversation.</li></ul><hr><h4 id="📋-16-6-—-in-chat-retrieval-provenance" tabindex="-1">📋 16.6 — In-chat retrieval provenance <a class="header-anchor" href="#📋-16-6-—-in-chat-retrieval-provenance" aria-label="Permalink to &quot;📋 16.6 — In-chat retrieval provenance&quot;">​</a></h4><p><strong>Goal:</strong> Make it visible when an answer came from the knowledge base, and what it came from.</p><p><strong>Deliverables:</strong></p><ul><li>A receipt in the chat thread when retrieval contributed to a reply, reusing task 2.5&#39;s existing connector-provenance pattern and its visual language rather than inventing a second one.</li><li>The receipt distinguishes source kinds — the user&#39;s own document, their own past message, or a past assistant reply — because the trust weight of those three differs, and the third is the one research 0012 flags as capable of recycling the model&#39;s own mistakes.</li></ul><p><strong>Dependencies:</strong> 16.5.</p><p><strong>Review checklist:</strong></p><ul><li>A retrieval-backed reply shows a receipt; a reply with no retrieval shows none.</li><li>Source kind is correct for each of the three cases.</li></ul><hr><h4 id="📋-16-7-—-user-content-plain-text-and-markdown" tabindex="-1">📋 16.7 — User content: plain text and markdown <a class="header-anchor" href="#📋-16-7-—-user-content-plain-text-and-markdown" aria-label="Permalink to &quot;📋 16.7 — User content: plain text and markdown&quot;">​</a></h4><p><strong>Goal:</strong> Let the user add their own content, starting with the formats that need no new native surface.</p><p><strong>Deliverables:</strong></p><ul><li>Import via <code>expo-document-picker</code> for <code>.txt</code> and <code>.md</code>, into the same archive/index the conversations use.</li><li>A list of imported documents with the ability to remove one (removing its chunks and vectors with it).</li><li>Re-importing a changed file updates it rather than duplicating it.</li></ul><p><strong>Dependencies:</strong> 16.4. Independent of 16.5/16.6.</p><p><strong>Review checklist:</strong></p><ul><li>An imported markdown file is retrievable in chat after indexing.</li><li>Removing a document removes its chunks — verified by the same question no longer being answerable.</li><li>This is research 0006&#39;s option C stage one, and ships without waiting on 16.8.</li></ul><hr><h4 id="📋-16-8-—-pdf-text-layer-extraction" tabindex="-1">📋 16.8 — PDF text-layer extraction <a class="header-anchor" href="#📋-16-8-—-pdf-text-layer-extraction" aria-label="Permalink to &quot;📋 16.8 — PDF text-layer extraction&quot;">​</a></h4><p><strong>Goal:</strong> Extend import to PDFs with a real text layer.</p><p><strong>Deliverables:</strong></p><ul><li>iOS: PDFKit&#39;s <code>PDFDocument.string(forPage:)</code>, no third-party dependency.</li><li>Android: resolves research 0006&#39;s still-open library spike (PdfBox-Android or an alternative) — the choice is part of this task, not a prerequisite to it.</li><li>OCR and scanned/image-only PDFs remain <strong>out of scope</strong>, per 0006&#39;s standing decision; a PDF with no text layer fails with an honest message rather than silently importing nothing.</li></ul><p><strong>Dependencies:</strong> 16.7.</p><p><strong>Review checklist:</strong></p><ul><li>A text-layer PDF imports and is retrievable on both platforms.</li><li>A scanned PDF fails with a clear explanation, not an empty document.</li></ul><hr><h4 id="📋-16-9-—-desktop-port" tabindex="-1">📋 16.9 — Desktop port <a class="header-anchor" href="#📋-16-9-—-desktop-port" aria-label="Permalink to &quot;📋 16.9 — Desktop port&quot;">​</a></h4><p><strong>Goal:</strong> The same knowledge base on desktop.</p><p><strong>Deliverables:</strong></p><ul><li>The embedding model added to <code>apps/desktop/src-tauri/src/models/catalog.rs</code>, matching 16.1&#39;s mobile entry.</li><li>Embedding in the Rust engine via <code>llama-cpp-2</code>&#39;s <code>embeddings_ith</code> / <code>embeddings_seq_ith</code>, with its own embeddings-enabled context and pooling type.</li><li>Archive, index, retrieval, provenance, and import — the desktop equivalents of 16.2–16.7.</li></ul><p><strong>Dependencies:</strong> 16.1–16.7.</p><p><strong>Review checklist:</strong></p><ul><li><strong>Desktop persists no chat history at all today</strong> — nothing in <code>apps/desktop/src/chat/</code> writes it, so conversations vanish on quit. This task therefore builds the archive from nothing rather than porting a working store, and is scoped accordingly. Confirm this is still true before starting; it may have changed.</li><li>Feature parity with mobile, verified by exercising the app, not only by the test suite.</li></ul><hr><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../research/0012-knowledge-base-and-retrieval.html">research 0012</a> — the decision record behind this epic, including the remote knowledge base (options B and C) deferred to a second phase</li><li><a href="./../../research/0006-files-document-summarization.html">research 0006</a> — why document input is a chat feature and not a connector, and the PDF extraction staging 16.7/16.8 follow</li><li><a href="./../../research/0003-model-verification-hashing.html">research 0003</a> — the precedent for measuring before designing, cited by 16.1 and 16.4</li><li><a href="./core-inference-chat.html">Core Inference &amp; Chat</a> — the offline pipeline retrieval feeds into</li><li><a href="./connector-framework.html">Connector Framework</a> — task 2.5&#39;s provenance pattern, reused by 16.6; and the layer the <em>second</em> phase will use</li></ul>',84)])])}const u=t(a,[["render",s]]);export{g as __pageData,u as default};
